// Helper model state
logic apb_busy;
logic outst;
logic rd_q;

wire w_setup = i_rst_n_core && i_apb_psel && !i_apb_penable && !apb_busy;
wire w_legal = (i_apb_paddr[1:0] == 2'b00) && (!i_apb_pwrite || (i_apb_pstrb == 4'b1111));
wire w_a_acc = o_tlul_a_valid && i_tlul_a_ready;
wire w_resp  = i_rst_n_core && o_tlul_d_ready && i_tlul_d_valid && (outst || w_a_acc);
wire w_err   = i_tlul_d_error
            || (i_tlul_d_opcode != (rd_q ? 3'b001 : 3'b000))
            || (i_tlul_d_source != PARA_SRC_W'(PARA_SRC_ID));
wire w_orphan = i_rst_n_core && i_tlul_d_valid && !w_resp;
wire w_ill_setup = w_setup && !w_legal;

always_ff @(posedge i_clk_core) begin
  if (!i_rst_n_core) begin
    apb_busy <= 1'b0;
    outst    <= 1'b0;
    rd_q     <= 1'b0;
  end else begin
    if (o_apb_pready)    apb_busy <= 1'b0;
    else if (w_setup)    apb_busy <= 1'b1;
    if (w_setup) rd_q <= !i_apb_pwrite;
    if (w_resp)          outst <= 1'b0;
    else if (w_a_acc)    outst <= 1'b1;
  end
end

// CHK-005: Legal Setup launches channel A in the first Access cycle (early launch) (BR-1.1-02, BR-3-01, BR-3-02, BR-3-12, BR-5.3-01, BR-5.3-02, BR-5.3-04, BR-5.3-11, BR-6.2-06, BR-10.1-01, BR-10.3-03, BR-15.3-08, BR-15.3-10, BR-20-12, BR-1.3-01, BR-1.3-02)
a_CHK_005: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) w_setup |-> (!o_apb_pready && !o_tlul_a_valid))
  else begin fails_CHK_005++; $display("NNC_FAIL CHK-005 @%0t", $time); end
a_CHK_005_b: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) (w_setup && w_legal) |=> (o_tlul_a_valid && !o_apb_pready && !o_apb_pslverr))
  else begin fails_CHK_005++; $display("NNC_FAIL CHK-005 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (w_setup)) hits_CHK_005 <= hits_CHK_005 + 1;

// CHK-006: Illegal Setup gives a local error in the first Access cycle with no TL-UL request (BR-T1-03, BR-T1-04, BR-T1-05, BR-2.3-01, BR-2.3-02, BR-3-24, BR-3-25, BR-3-36, BR-5.4-05, BR-9-04, BR-10.1-02, BR-10.3-01, BR-12-01, BR-12-02, BR-12-04, BR-15.3-07, BR-15.3-10, BR-20-05, BR-1.1-04)
a_CHK_006: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) w_ill_setup |=> (o_apb_pready && o_apb_pslverr && (o_apb_prdata == 32'h0) && !o_tlul_a_valid))
  else begin fails_CHK_006++; $display("NNC_FAIL CHK-006 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (w_ill_setup)) hits_CHK_006 <= hits_CHK_006 + 1;

// CHK-007: Accepted TL-UL response is mapped to the APB completion in the next cycle (BR-3-09, BR-3-10, BR-3-26, BR-3-27, BR-3-28, BR-5.3-06, BR-5.3-07, BR-9-09, BR-9-10, BR-10.1-03, BR-10.1-05, BR-12-05, BR-12-07, BR-20-10, BR-1.3-04, BR-6.3-14, BR-6.3-15, BR-8-04, BR-11-02, BR-6.2-04, TL-T4.1.3.4-08)
a_CHK_007: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) w_resp |=> (o_apb_pready && (o_apb_pslverr == $past(w_err)) && (o_apb_prdata == (($past(rd_q) && !$past(w_err)) ? $past(i_tlul_d_data) : 32'h0))))
  else begin fails_CHK_007++; $display("NNC_FAIL CHK-007 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (w_resp)) hits_CHK_007 <= hits_CHK_007 + 1;

// CHK-008: PREADY only as the result of an illegal Setup or an accepted response (BR-12-09, BR-20-07, BR-1.1-01, BR-10.1-05, BR-10.1-06, BR-5.4-04)
a_CHK_008: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) (o_apb_pready && $past(i_rst_n_core)) |-> ($past(w_ill_setup) || ($past(w_resp) && $past(apb_busy))))
  else begin fails_CHK_008++; $display("NNC_FAIL CHK-008 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (o_apb_pready && $past(i_rst_n_core))) hits_CHK_008 <= hits_CHK_008 + 1;

// CHK-009: Orphan response has no APB effect (BR-3-11, BR-6.3-08, BR-10.1-06, BR-15.3-09, TL-T4.1.3.5-08)
a_CHK_009: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core) (w_orphan && !w_ill_setup) |=> (!o_apb_pready && !o_apb_pslverr && (o_apb_prdata == $past(o_apb_prdata))))
  else begin fails_CHK_009++; $display("NNC_FAIL CHK-009 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (w_orphan && !w_ill_setup)) hits_CHK_009 <= hits_CHK_009 + 1;
